    unsigned int level;
    unsigned int edge;
    unsigned int debounce;
    unsigned int delay;
}omap2_gpio_s;

static unsigned int omap2_gpio_module_read(void *opaque, unsigned int addr)
{
    struct omap2_gpio_s *s = (struct omap2_gpio_s *) opaque;

